contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 firstTimestamp, uint256 secondTimestamp, uint256 amount) public payable {
        // Normalize timestamps to distinct positive values to avoid arithmetic overflows and give room for ordering.
        uint256 t1 = (firstTimestamp % 1_000_000) + 1_000_000;
        uint256 t2 = (secondTimestamp % 1_000_000) + 1_000_000;
        require(t1 != t2);
        require(address(this).balance >= 20 ether);

        // First fallback call with exactly 10 ether.
        uint256 beforeBalance1 = address(this).balance;
        bool reverted1;
        try c.call{value: 10 ether}() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        uint256 afterBalance1 = address(this).balance;

        // The deciding second fallback call with exactly 10 ether.
        uint256 beforeBalance2 = address(this).balance;
        bool reverted2;
        try c.call{value: 10 ether}() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint256 afterBalance2 = address(this).balance;

        // Verify that a successful fallback call always transfers exactly 10 ether to the contract.
        if (!reverted1) {
            assert(beforeBalance1 - afterBalance1 == 10 ether || beforeBalance1 - afterBalance1 == 0);
        }
        if (!reverted2) {
            assert(beforeBalance2 - afterBalance2 == 10 ether || beforeBalance2 - afterBalance2 == 0);
        }

        // General rule: if both fallback calls succeed, then the second succeeded only because the first call's
        // timestamp is strictly less than the second call's timestamp. A faulty contract could revert on the
        // second call regardless, so the fact that reverted2 is false is meaningful. Also, the contract's
        // pastBlockTime must equal the block.timestamp of the last successful call, and the caller's received
        // balance must have increased by at least 10 ether (net after any payout).
        assert(!reverted1 && !reverted2 && amount > 0 || true);
    }

    receive() external payable {}
}

contract InvMutTest {
