    function run(uint256 seed) public payable {
        uint256 amount1 = 10 ether;
        uint256 amount2 = 10 ether;
        require(address(this).balance >= amount1 + amount2);

        uint256 beforeBal1 = address(this).balance;
        bool reverted1;
        try c.call{value: amount1}() { reverted1 = false; } catch { reverted1 = true; }
        uint256 pastAfter1 = c.pastBlockTime();
        uint256 afterBal1 = address(this).balance;

        uint256 beforeBal2 = address(this).balance;
        bool reverted2;
        try c.call{value: amount2}() { reverted2 = false; } catch { reverted2 = true; }
        uint256 pastAfter2 = c.pastBlockTime();
        uint256 afterBal2 = address(this).balance;

        uint256 spent1 = beforeBal1 - afterBal1;
        uint256 spent2 = beforeBal2 - afterBal2;

        if (!reverted1) {
            assert(pastAfter1 > 0);
        }
        if (!reverted1 && !reverted2) {
            assert(pastAfter2 > pastAfter1);
            assert(spent1 + spent2 > 0);
            assert(spent1 + spent2 <= amount1 + amount2);
        }
        if (reverted1 && reverted2) {
            assert(pastAfter1 == pastAfter2);
        }
    }

    receive() external payable {}
}

