contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 preSeed) public payable {
        // Ensure the tester can supply exactly 10 ether.
        require(address(this).balance >= 10 ether);

        // Make an initial acceptance with a fixed timestamp, if allowed by the current chain state.
        // We cannot control block.timestamp directly, but we can observe it and use it in the rule.
        // If the current timestamp is not yet past pastBlockTime, don't seed; otherwise seed so the
        // main call can be tested for both success and revert depending on timestamp.
        uint256 t0 = block.timestamp;
        if (t0 > c.pastBlockTime()) {
            // This is a state-changing call; it must be its own top-level statement.
            c.fallback{value: 10 ether}();
        }

        // Capture before-values.
        uint256 beforePast = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;

        // Attempt the fallback with exactly 10 ether; observe whether it reverts.
        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Capture after-values.
        uint256 afterPast = c.pastBlockTime();
        uint256 afterBal = address(c).balance;

        // General rule: the fallback only succeeds when the current block timestamp is strictly
        // greater than the stored pastBlockTime, and on success it updates pastBlockTime to the
        // current timestamp while increasing the contract's Ether balance by exactly 10 ether
        // (unless the block number triggers the 15-block payout).
        if (!reverted) {
            // Success implies strict timestamp increase and balance gain of 10 ether minus any payout.
            // The payout condition depends on block.number % 15 == 0; we cannot predict the payout
            // without reading block.number, but the rule must hold for all inputs. On success the
            // previous timestamp must have been strictly less than the new timestamp, and the new
            // stored timestamp must equal the current block timestamp.
            assert(afterPast == block.timestamp && afterPast > beforePast);
        } else {
            // Revert implies the timestamp precondition failed; the state must be unchanged.
            assert(afterPast == beforePast && afterBal == beforeBal);
        }
    }

    receive() external payable {}
}

