    }

    function run(uint256 amount, uint256 timeAdvance) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Advance the chain timestamp so that the first call can succeed if desired.
        if (timeAdvance > 0) {
            require(timeAdvance <= block.timestamp);
            assembly {
                pop(call(gas(), 0, 0, 0, 0, 0, 0))
            }
            // The above does not change time; use vm-like behavior is not allowed.
            // Instead, rely on the fact that the test harness may use a fresh chain,
            // and make the call sequential to demonstrate the monotonicity rule.
        }

        uint256 beforeTime = c.pastBlockTime();
        bool reverted;
        try c.call{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTime = c.pastBlockTime();

        // Rule: if the call succeeds, the stored pastBlockTime must equal the current timestamp
        // and must be greater than the previous stored value (strict advancement).
        // If the call reverts, the stored time must remain unchanged.
        assert(reverted ? afterTime == beforeTime : (afterTime == block.timestamp && afterTime > beforeTime));
    }

    receive() external payable {}
}

