    function run(uint amount) public payable {
        // Ensure we can send `amount` wei to c.
        require(address(this).balance >= amount);

        // First, establish a successful call at a fresh timestamp: must be 10 ether.
        uint balBefore = address(c).balance;
        c.fallback{value: 10 ether}();
        uint t1 = c.pastBlockTime();
        uint balAfterPaid = address(c).balance;

        // Second call with the caller's chosen amount. Precondition: one more wei
        // is available for the effective probe value when amount == 10 ether.
        require(amount != 10 ether || address(this).balance >= 1 wei);
        uint probe = (amount == 10 ether && address(this).balance < 10 ether) ? amount + 1 wei : amount;

        bool reverted;
        uint balBeforeProbe = address(c).balance;
