        uint t2 = c.pastBlockTime();

        if (amount != 10 ether) {
            // Wrong value (including < 10 ether, or > 10 ether which c cannot accept)
            // must revert and leave all state untouched.
            assert(reverted && t2 == t1 && balAfterProbe == balBeforeProbe);
        } else {
            // Exactly 10 ether: must not revert; pastBlockTime advances to the
            // call's timestamp; balance changes only by exactly 10 ether
            // (an eventual payout from c can only reduce c's balance by the
            //  amount held before this call).
            assert(!reverted && t2 > t1 && balAfterProbe == balBeforeProbe + 10 ether);
        }
    }

    receive() external payable {}
}

