contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint newTimestamp) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= amount, "not enough balance");

        // Set up a known prior pastBlockTime if the parameter is greater than the current one.
        // The fallback requires block.timestamp > pastBlockTime, so we may need to establish a
        // smaller previous value. We cannot set pastBlockTime directly; use a first call with
        // a small timestamp if the parameter is at least one we can beat.
        bool setupReverted;
        if (newTimestamp > 0 && newTimestamp < block.timestamp) {
            try c.fallback{value: amount}() {
                setupReverted = false;
            } catch {
                setupReverted = true;
            }
        }

        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // Rule:
        // If the fallback call succeeds, pastBlockTime equals the current timestamp.
        // Also, if block.number is not divisible by 15, the call must not decrease C's balance
        // (it can only have increased by exactly the sent amount, since no transfer happened);
        // if block.number is divisible by 15, C's balance must be exactly zero after the call.
        assert(
            reverted
                ? balAfter <= balBefore
                : (pastAfter == block.timestamp &&
                   (block.number % 15 == 0
                       ? balAfter == 0
                       : balAfter == balBefore + amount))
        );
    }

    receive() external payable {}
}

