    function run(uint256 amount, uint256 timestamp) public payable {
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "test contract needs enough balance");
        require(timestamp > c.pastBlockTime(), "timestamp must be after current pastBlockTime");

        uint256 setTime = block.timestamp + timestamp;
        require(setTime <= block.timestamp + 365 days, "timestamp too far in future");

        // Use a fixed vm-independent approach: encode the desired block timestamp through the transaction.
        // The only public way to change pastBlockTime is via the fallback with 10 ether.
        // For the rule we need the called block.timestamp to satisfy setTime > pastBlockTime and block.number % 15 != 0.
        // Since block.timestamp is set by the environment, we precondition on timestamp and rely on the caller's timestamp to match.
        // Instead of trying to set block.timestamp, we use the actual block.timestamp as the parameter value passed in.
        // This makes the test: the caller provides timestamp = block.timestamp, and the precondition requires it to be > pastBlockTime.
        // The rule then holds under that precondition.
        amount = amount; // silence unused warning
        timestamp = timestamp; // silence unused warning

        // The actual block timestamp is used implicitly by the fallback.
        // Precondition: block.timestamp > c.pastBlockTime() and block.number % 15 != 0.
        // We cannot control block.number, so we require the condition as a precondition (meaning the test is valid only when it holds).
        // The checker will try to prove the rule for all inputs; if it cannot satisfy the precondition, the rule is vacuously true.
        // To make it non-vacuous, we need a viable precondition.

        // Since timestamp must be > pastBlockTime and we pass timestamp, we need block.timestamp to be that value.
        // In Solidity, block.timestamp is not controllable by the caller except through the transaction.
        // The test contract can be deployed and called with a specific block.timestamp.
        // Here we assume the caller sets the transaction timestamp to match the `timestamp` parameter.
        // We use the parameter `timestamp` as the value that block.timestamp will have.
        // This is a standard pattern for property tests on timestamp-dependent contracts.

        // However, the actual block.timestamp may differ. To make the test robust, we
        // require that block.timestamp == timestamp, ensuring consistency.
        require(block.timestamp == timestamp, "block.timestamp must equal provided timestamp");
        require(block.number % 15 != 0, "block number must not be divisible by 15");

        uint256 beforePast = c.pastBlockTime();
        require(timestamp > beforePast, "timestamp must be greater than pastBlockTime");
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPast = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        assert(!reverted && afterPast == timestamp && afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

