    constructor(C _c) { c = _c; }
    function run(uint256 sendAmount) public payable {
        require(sendAmount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= sendAmount, "insufficient balance");

        // Ensure a fresh timestamp: advance c.pastBlockTime by funding the contract directly.
        // This does not call fallback, so it does not change pastBlockTime.
        address(c).transfer(1 wei);

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeTestBalance = address(this).balance;
        uint256 blockNumber = block.number;

        bool reverted;
        try c.fallback{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTime = c.pastBlockTime();
        uint256 afterContractBalance = address(c).balance;
        uint256 afterTestBalance = address(this).balance;

        if (blockNumber % 15 == 0) {
            assert(!reverted
                && afterTime == block.timestamp
                && afterContractBalance == 0
                && afterTestBalance == beforeTestBalance - sendAmount + beforeContractBalance + sendAmount);
        } else {
            assert(!reverted
                && afterTime == block.timestamp
                && afterContractBalance == beforeContractBalance + sendAmount
                && afterTestBalance == beforeTestBalance - sendAmount);
        }
    }
    receive() external payable {}
}

