contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint timestamp) public payable {
        // Ensure the contract can send exactly 10 ether.
        require(address(this).balance >= 10 ether);

        // The fallback requires the call timestamp to be strictly greater than pastBlockTime.
        uint before = c.pastBlockTime();
        require(timestamp > before);

        uint balanceBefore = address(this).balance;

        // Make the deciding call with exactly 10 ether.
        bool reverted;
        try c.call{value: 10 ether}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // On success, pastBlockTime is updated to the timestamp used by the call,
        // and the caller's net Ether decreases by exactly 10 ether.
        assert(
            reverted ||
                (c.pastBlockTime() == timestamp &&
                    balanceBefore == address(this).balance + 10 ether)
        );
    }
}

