    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint useAmountFlag) public payable {
        uint sentAmount = useAmountFlag == 0 ? 10 ether : amount;
        require(address(this).balance >= sentAmount, "insufficient balance");

        uint beforeTime = c.pastBlockTime();
        uint beforeBal = address(c).balance;
        bool reverted;
        try c.call{value: sentAmount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBal = address(c).balance;

        if (reverted) {
            assert(afterBal == beforeBal);
            assert(afterTime == beforeTime);
        } else {
            assert(sentAmount == 10 ether);
            assert(afterTime > beforeTime);
            assert(afterTime == block.timestamp);
            if (block.number % 15 == 0) {
                assert(afterBal == 0);
            } else {
                assert(afterBal == beforeBal + sentAmount);
            }
        }
    }

    receive() external payable {}
}

