        // Read the current pastBlockTime based on the chosen timestamp.
        uint256 initialPastBlockTime = c.pastBlockTime();

        // Ensure the balance is sufficient and prepare to call.
        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.pastBlockTime() == timestamp);
